"""Sign: y = 1 where x >= 0, else -1."""

import numpy as np
from gnuradio import gr


class blk(gr.sync_block):
    """Sign: y = 1 where x >= 0, else -1."""

    def __init__(self):
        gr.sync_block.__init__(self, name="Sign", in_sig=[np.float32], out_sig=[np.float32])

    def work(self, input_items, output_items):
        x = input_items[0]
        output_items[0][:] = np.where(x >= 0, 1.0, -1.0)
        return len(output_items[0])
